using static StrataLint.Scribe.DefinitionDsl;
using static StrataLint.Scribe.FormulaDsl;
using F = StrataLint.Scribe.FormulaDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.Observer.Linear;

internal sealed class DerivativeLayerNativeGramianDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Invertible physical scaling and native Gramian limit", H("Invertible physical scaling and native Gramian limit"), Blocks(
            Describe.Lean(DescribeId.Create("derivative-layer-native-gramian"),
                DeclarationHandle.Create("D5/S3/Observer/Linear/DerivativeLayerNativeGramian.derivative_layer_native_gramian"),
                H("Invertible physical scaling and native Gramian limit"), StatementSource.FromAuthor(TheoremFormula()),
                AssessedProvenance.FromRepo(), Blocks(
                    Paragraph(Text("Let V be an arbitrary finite-dimensional real inner-product space, and W an arbitrary complete real inner-product space. Let B:V→V and C:V→W be arbitrary linear maps. Neither observability of the whole V nor a positive dimension is assumed.")),
                    Paragraph(Text("Put n=dim V, N(j)=the intersection of ker(C B^k) for 0≤k<j, U=N(n) orthogonal complement, E(j)=N(j) intersect N(j+1) orthogonal complement for 0≤j<n. Pi(j):V→V is the actual orthogonal projection onto E(j). All n layer indices are retained, even when their layer is zero. Write b and c for the continuous linear maps associated to B and C; i:U→V is the inclusion. All norms are induced Hilbert operator norms.")),
                    Paragraph(Text("On U let Q(j) be Pi(j) restricted to U, with its range returned to U by the orthogonal projection onto U. Put d(T)=sum sqrt(T) T^j Q(j) and e(T)=sum (sqrt(T) T^j)^(-1) Q(j). Define A(t)=c exp(t b) i and G(T)=the interval integral from zero to T of A(t) adjoint composed with A(t).")),
                    Paragraph(Text("Put P(s)=sum over j<n of s^j/j! c b^j Pi(j) i and H=the interval integral from zero to one of P(s) adjoint composed with P(s). Write Z(T,s)=sqrt(T) A(T s) e(T). Composition is written by juxtaposition in the display, and a star denotes the Hilbert adjoint.")),
                    Paragraph(Text("For every T>0, d(T)e(T) and e(T)d(T) both equal the identity on U, and e(T)G(T)e(T) equals the integral of Z(T,s) adjoint composed with Z(T,s). H has positive quadratic form at every nonzero state. There is R≥0 for which the linear error holds whenever 0<T≤1 and T times the norm of b is less than one.")),
                    Paragraph(Text("Projection orthogonality gives the inverse equations without a rank premise. The physical change of variables t=T s and self-adjointness of the scaling give the integral identity. Uniform normalized-trajectory convergence controls the difference of the two squared operators and its integral.")),
                    Paragraph(Text("For the observable Euclidean application, fix arbitrary d,p≥1 and matrices B∈R^(d×d), C∈R^(p×d) with (C,B) observable, and use their associated linear maps on V=R^d and W=R^p. The derivative filtration in "), Ref("D5/S3/Observer/Linear/DerivativeLayerNormalizedObservation.derivative_layer_normalized_observation"), Text(" has N(d)=0, so U is the whole state space. Let m be the least j with N(j+1)=0; then 0≤m<d. For j>m, N(j)=0 and E(j)=0. Thus the supplier sums over j<d reduce exactly to j=0,...,m, retaining every layer in that range and the actual exponential trajectory.")),
                    Paragraph(Text("The finite orthogonal decomposition R^d=the orthogonal sum of E(j), 0≤j≤m, supplies a subordinate orthonormal basis e_i. The upstream subordinateOrthonormalBasis and subordinateOrthonormalBasisIndex construction, followed by reindexing with Tuple.sort, orders the layer labels w_i increasingly. Each e_i belongs to E(w_i), and #{i:w_i=j}=d_j=dim E(j) for every 0≤j≤m, including zero-dimensional groups. Fix any such ordered subordinate basis for all subsequent identities and estimates; no choice of minimal layers or subordinate basis imposes an additional hypothesis on B or C.")),
                    Paragraph(Text("Let S have columns e_i in standard coordinates. The operator G(T) above has standard matrix G_standard(T)=the integral from zero to T of exp(t Bᵀ) Cᵀ C exp(t B), and matrix G_L(T)=Sᵀ G_standard(T) S in this basis. For x=sum x_j with x_j∈E(j), P(s)x=sum s^j C B^j x_j/j!, with j=0,...,m. If P_L(s) has columns P(s)e_i, put M_L=the integral from zero to one of P_L(s)ᵀ P_L(s). Thus M_L is the matrix of the constant limit operator H above in the same basis. Since S is orthogonal, these coordinate changes preserve the Euclidean operator norm and the spectrum, and det G_L(T)=det G_standard(T) because det(S)^2=1.")),
                    Paragraph(Text("For T>0 the physical scaling D_T=d(T) acts on E(j) by sqrt(T) T^j=T^(j+1/2). Its matrix is D(T)=diag(sqrt(T) T^(w_i)), and e(T) is its two-sided inverse. Write H(T)=D(T)^(-1) G_L(T) D(T)^(-1) for the normalized matrix family, distinguishing it from the constant operator H above. The exact identity is G_L(T)=D(T) H(T) D(T). All short-time estimates fix B,C, the Euclidean norms, the time unit and the chosen basis, and take T down to zero through positive values.")),
                    Paragraph(Text("For x_j∈E(j), C B^k x_j=0 when k<j. The exact factorial Taylor estimate in "), Ref("D5/S3/Observer/Linear/ExactTaylorObservationRemainder.norm_observation_taylor_remainder"), Text(" gives, for some fixed K₀≥0 and δ>0, the operator norm bound ‖sqrt(T) C exp(Ts B) D_T^(-1)-P(s)‖≤K₀ T simultaneously for every 0<T<δ and s∈[0,1]. Integrating the difference of the squared operators gives ‖H(T)-M_L‖≤K T for fixed K≥0 after shrinking δ. The supplier conditions T≤1 and T‖B‖<1 are ensured, for example, by also taking δ≤min(1,1/(1+‖B‖)). Hence H(T) tends to this same M_L along nhdsWithin(0,Ioi(0)), in the induced Euclidean operator norm.")),
                    Paragraph(Text("Positivity of the same M_L follows from "), Ref("D5/S3/Observer/Linear/DerivativeLayerGramianPositivity.derivative_layer_gramian_pos"), Text(": zero polynomial energy makes every coefficient C B^j x_j vanish; then x_j belongs both to N(j+1) and its orthogonal complement, so each x_j=0. Separately, for every T>0, "), Ref("D5/S3/Observer/Linear/ObservableTrajectoryCoordinates.observable_trajectory_coordinates"), Text(" identifies the actual physical Gramian with F*F for the injective trajectory map F:x↦(t↦C exp(t B)x) in L²(0,T). Thus G(T), G_standard(T) and G_L(T) are positive definite for every positive T, providing positivity of the same congruence used below.")),
                    Paragraph(Text("Choose a fixed μ>0 with xᵀ M_L x≥μ‖x‖². For sufficiently small positive T the norm error is at most μ/2, so a I≼H(T)≼b I with fixed a=μ/2>0 and b=‖M_L‖+μ/2>0. Congruence by the same D(T) gives a D(T)^2≼G_L(T)≼b D(T)^2. Equivalently, for every state x, a‖D_T x‖²≤⟨x,G(T)x⟩≤b‖D_T x‖². Taking a common smaller positive radius preserves all these bounds. The right-sided convergence, positive M_L, increasing w_i and positive actual congruence are exactly the inputs of "), Ref("D5/S3/Observer/Linear/GradedCongruenceSpectrum.graded_congruence_spectrum"), Text("; its application below gives every sorted spectral index and every layer group.")),
                    Paragraph(Text("The same multiplicities give q=sum_i(2w_i+1)=sum over j=0,...,m of (2j+1)d_j. For every T>0, det(D(T)^2)=the product of T^(2w_i+1)=T^q, and the exact congruence yields det G_standard(T)=det G_L(T)=T^q det H(T). Determinant is a C¹ polynomial on this fixed finite matrix space, hence locally Lipschitz at this same M_L. Combining that local bound with ‖H(T)-M_L‖≤K T gives fixed K_det≥0 and δ_det>0 with |det H(T)-det M_L|≤K_det T for 0<T<δ_det.")),
                    Paragraph(Text("In particular |det G_standard(T)/T^q-det M_L|≤K_det T. With r(T)=det H(T)-det M_L, the same actual Gramian satisfies det G_standard(T)=T^q(det M_L+r(T)), |r(T)|≤K_det T, so det G_standard(T)=T^q(det M_L+O(T)). The leading coefficient is the positive determinant of the literal integral of P_L(s)ᵀ P_L(s) in the fixed subordinate orthonormal basis. Orthogonal invariance also identifies it with the determinant of the polynomial-limit operator in standard coordinates.")),
                    Paragraph(Text("Two-oscillator modal application. In the energy coordinates x=(q1,p1,q2,p2), take B=diag(J2,2 J2), with J2=[[0,1],[-1,0]], and energy ||x||²/2. This is the constant coordinate change x=L z, L=diag(1,1,2,1), from Poisson matrix diag(J2,J2) and positive energy matrix diag(1,1,4,1): LᵀL is that energy matrix and L diag(J2,J2) Lᵀ=B. The transformed generator is the same B, since L diag(J2,J2) diag(1,1,4,1) L⁻¹=B.")),
                    Paragraph(Text("For C_sum, the ordered orthonormal layer vectors are (1,0,1,0)/sqrt(2), (0,1,0,2)/sqrt(5), (1,0,-1,0)/sqrt(2), and (0,2,0,-1)/sqrt(5), with weights (0,1,2,3). For C_sep they are the coordinate vectors in the order (q1,q2,p1,p2), with weights (0,0,1,1). For every natural j, the actual derivative kernel N(j) is the span of vectors whose weight is at least j, and E(j) is the span of vectors whose weight equals j. Thus the cumulative ranks are (0,1,2,3,4) and (0,2,4), the last layer indices are 3 and 1, and the nonzero layer dimensions are (1,1,1,1) and (2,2), respectively. Both finite jets are injective.")),
                    Paragraph(Text("In these actual layer coordinates, P_sum(s)=(2/sqrt(2),5s/sqrt(5),3s²/(2sqrt(2)),s³/sqrt(5)) and P_sep(s)=[[1,0,s,0],[0,1,0,2s]]. These are obtained from the orthogonal projections onto the derivative layers, with coefficients C B^j/j!. Entrywise application of the scalar monomial integral identifies the integrals of P(s)ᵀP(s). For the sum sensor the integral is R diag(a) H3 diag(a) R, where R=diag(1/sqrt(2),1/sqrt(5),1/sqrt(2),1/sqrt(5)), a=(2,5,3/2,1), and H3 has entries 1/(i+j+1), for i,j=0,...,3. For the split sensor it is [[1,0,1/2,0],[0,1,0,1],[1/2,0,1/3,0],[0,1,0,4/3]].")),
                    Paragraph(Text("The determinant of the four-row Taylor matrix with rows C_sum B^j/j! is 3/2, det H3=1/6048000, and the determinants of the two actual polynomial integrals above are 1/2688000 and 1/36. For every T>0 the same physical Gramian satisfies det G_sum(T)/T^16=det H_sum(T) and det G_sep(T)/T^8=det H_sep(T), where H(T)=D(T)^(-1)SᵀG(T)S D(T)^(-1) in the corresponding fixed basis. The sum-side physical determinant limit additionally requires transporting the generic normalized-operator estimate through these explicit coordinates; the polynomial coefficient alone does not supply that physical identification.")),
                    Paragraph(Text("For nonzero real frequency omega, put B_omega=[[0,omega],[-omega,0]] and C_omega=(1,0). The real regular representation of complex multiplication transports the complex exponential to exp(t B_omega)=[[cos(omega t),sin(omega t)],[-sin(omega t),cos(omega t)]]. Thus the literal sensor Gramian is the integral of the outer product (cos(omega t),sin(omega t)) with itself; this identifies it with the physical exponential-integral definition. The exponential transport applies Mathlib’s NormedSpace.map_exp and Algebra.leftMulMatrix_complex.")),
                    Paragraph(Text("Entrywise integration gives G_omega(T)=[[T/2+sin(2 omega T)/(4 omega),(1-cos(2 omega T))/(4 omega)],[(1-cos(2 omega T))/(4 omega),T/2-sin(2 omega T)/(4 omega)]]. Its determinant is (T²-sin²(omega T)/omega²)/4. These identities hold for every real T whenever omega is nonzero. The entries use the existing integral_cos_sq, integral_sin_sq and integral_sin_mul_cos₂ formulas.")),
                    Paragraph(Text("The limits sin(u)/u→1, (1-cos(u))/u²→1/2 and (u-sin(u))/u³→1/6 give det G_omega(T)/T⁴→omega²/12 as T decreases to zero through positive values. For example, factor u²-sin²(u)=(u-sin(u))(u+sin(u)), with u=omega T; this preserves the frequency factor in the coefficient. The two residual limits follow by applying HasDerivAt.lhopital_zero_nhdsNE to the existing trigonometric derivatives and sin(u)/u limit.")),
                    Paragraph(Text("For the actual split sensor C_sep=[[1,0,0,0],[0,0,1,0]], the same physical exponential and integral give G_sep(T)=diag(G_1(T),G_2(T)) in the ordered coordinates (q1,p1,q2,p2). Determinants therefore multiply, and det G_sep(T)/T⁸→(1/12)(4/12)=1/36. Both C_sep and C_sum=(1,0,1,0) have Tr(CᵀC)=2.")),
                    Paragraph(Text("This modal computation establishes the physical split-sensor determinant and its leading coefficient. The statistical conclusions for the same physical experiments follow from the trajectory, Gaussian and asymptotic interfaces applied below.")),
                    Paragraph(Text("The actual statistical experiment uses the same B, C_sum=(1,0,1,0), C_sep=[[1,0,0,0],[0,0,1,0]] and energy ||x||²/2. Fix any beta>0 and let X have the centered Gaussian law with covariance beta^(-1) I_4. For every T>0 let F_T x be the class of t↦C exp(tB)x in L²((0,T),R^p), with p=1 for sum and p=2 for split. Observability makes F_T injective, so its trajectory image has dimension four in both experiments. Choose any orthonormal basis of that actual image, independently for every positive T; no continuity or measurability in T of this choice is required.")),
                    Paragraph(Text("Let U_T take the coordinates of the orthogonal projection onto that trajectory image in the chosen basis, and let M_T=U_T F_T in standard state coordinates. On any probability space carrying measurable X and an independent standard Gaussian vector xi in R^4, the observed coordinate vector is Y_T=M_T X+sigma(T) xi. The physical identity M_TᵀM_T=G_standard(T) follows from the isometry on the image. Thus the response matrix and its spectrum are determined by the exponential trajectory; they are not additional inputs. The noise has covariance sigma(T)^2 I_4 in every such basis. The results hold for every real nonzero noise amplitude, including either sign.")),
                    Paragraph(Text("Write mu_T for the actual joint law of (Y_T,X). Information means the Radon–Nikodym Kullback–Leibler divergence I(T)=KL(mu_T || (mu_T)_Y tensor (mu_T)_X). The optimal energy risk is R(T)=inf_a E[||X-a(Y_T)||²/2], where a ranges over all measurable maps R^4→R^4 and the expectation is the nonnegative extended-real integral. Estimators of infinite risk are included in this infimum. For every positive T and sigma(T)≠0, both information and optimal risk are finite.")),
                    Paragraph(Text("Put tau=1/sigma(T)^2. The Gaussian observation law gives posterior covariance K_T=(beta I_4+tau G_standard(T))^(-1) and mean a_*(Y_T)=tau K_T M_TᵀY_T. Conditional Gaussian integration gives E[||X-a(Y_T)||²/2]=Tr(K_T)/2+E[||a_*(Y_T)-a(Y_T)||²/2] as an identity of nonnegative extended-real quantities. Hence the same measurable posterior mean attains the infimum even when competitors have infinite risk. If lambda_i(T) are the eigenvalues of this actual physical Gramian, then I(T)=(1/2) sum_i log(1+lambda_i(T)/(beta sigma(T)^2)) and R(T)=(1/2) sum_i sigma(T)^2/(beta sigma(T)^2+lambda_i(T)).")),
                    Paragraph(Text("The native normalized Gramian and graded-congruence spectrum give eigenvalue orders T,T^3,T^5,T^7 for the sum sensor and T,T,T^3,T^3 for the split sensor, counted with their actual layer multiplicities. Set sigma(T)^2=T^4 for every T>0, permitting any sign at each T. In the sum experiment the first two information terms contribute (3+1)/2=2 times log(1/T), while the other two remain bounded; exactly the two layers with powers 5 and 7 contribute beta^(-1)/2 each to the limiting risk. Thus I_sum(T)=2 log(1/T)+O(1) and R_sum(T)→beta^(-1). In the split experiment all four eigenvalues dominate the noise: the information coefficient is (2·3+2·1)/2=4 and every risk term tends to zero. Thus I_sep(T)=4 log(1/T)+O(1) and R_sep(T)→0.")),
                    Paragraph(Text("For each fixed real sigma≠0, apply the physical fixed-noise information expansion to the same trajectory and Gaussian laws. Both sensors have Tr(CᵀC)=2, so I(T)=T Tr(CᵀC)/(2 beta sigma²)+O(T²)=T/(beta sigma²)+O(T²). More explicitly, for each fixed beta>0 and sigma≠0 there exist K≥0 and delta>0 such that |I(T)-T/(beta sigma²)|≤K T² whenever 0<T≤delta, for either experiment and every trajectory-image basis choice. The constants may depend on beta and sigma; no uniformity over those parameters is asserted.")),
                    Paragraph(Text("All these limits are through positive T, and the experiment and exact Gaussian formulas hold for every positive T. The split filtration retains its zero layers at indices two and three; the cumulative rank at index zero is zero. No further layer nonemptiness or supplied canonical spectrum is assumed. These conclusions concern the full physical trajectory experiment. A finite collection of moments has a different finite-time Gramian and is not identified with the physical integral here.")),
                    Paragraph(Text("The trajectory and law identifications use "), Ref("D5/S3/Observer/Linear/ObservableTrajectoryCoordinates.observable_trajectory_coordinates_all_bases"), Text(" and "), Ref("D5/S3/Observer/Linear/GaussianObservationLaw.gaussian_observation_law_complete"), Text(". The spectral and fixed-noise consequences use "), Ref("D5/S3/Observer/Linear/GradedCongruenceSpectrum.graded_congruence_spectrum"), Text(", "), Ref("D5/S3/Observer/Linear/SpectralNoiseAsymptotics.spectral_noise_asymptotics"), Text(" and "), Ref("D5/S3/Observer/Linear/PhysicalFixedNoiseInformation.physical_fixed_noise_information"), Text(" with the actual parameter and law correspondence above.")),
                    Paragraph(Text("The finite derivative filtration supplies orthogonal geometry, while the exponential power series and Bochner integral supply the analytic operations."))), DescribeRole.Theorem))));

    private static Formula TheoremFormula()
    {
        Formula t = F.Id("T"), s = F.Id("s"), x = F.Id("x"), r = F.Id("R");
        Formula dt = App(F.Id("d"), t), et = App(F.Id("e"), t), gt = App(F.Id("G"), t);
        Formula h = F.Id("H"), z = App(F.Id("Z"), t, s);
        return Disp(Seq(Open, Forall, Sp, D(0), Lt, t, Comma, Sp,
            dt, et, Eq, F.Id("I"), Underscore, Grp(F.Id("U")), Sp, Land, Sp, et, dt, Eq, F.Id("I"), Underscore, Grp(F.Id("U")), Sp, Land, Sp,
            et, gt, et, Eq, Int, Underscore, Grp(D(0)), Caret, Grp(D(1)), Sp,
            z, Caret, Grp(Star), z, Sp, F.Id("d"), s, Close,
            RowBreak, Grp(), Land, Sp, Open, Forall, Sp, x, InMacro, Sp, F.Id("U"), Comma,
            x, Neq, Sp, D(0), Rightarrow, Sp, D(0), Lt, Langle, Sp, x, Comma, App(h,x), Rangle, Close,
            RowBreak, Grp(), Land, Sp, Open, Exists, Sp, r, Ge, Sp, D(0), Comma, Sp,
            Forall, Sp, t, Comma, Sp, Open, D(0), Lt, t, Le, Sp, D(1), Sp, Land, Sp,
            t, new Formula.Norm(F.Id("b")), Lt, D(1), Close, Sp, Rightarrow, Sp,
            new Formula.Norm(Seq(et,gt,et,Minus,h)), Le, Sp, r,t, Close));
    }

    private static Formula App(Formula function, params Formula[] arguments) =>
        new Formula.Apply(function, [.. arguments]);
}
